cat > /workspace/main.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"os"
)

const version = "v0.0.0"

const usage = `Usage: %s [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version
`

type Options struct {
	From       byte // 'y','t','j','c'
	To         byte
	FromName   string
	ToName     string
	Indent     bool
	Escape     bool
	Keys       bool
	NoConvert  bool
}

func printUsage(w io.Writer, prog string) {
	fmt.Fprintf(w, usage, prog)
}

func formatName(c byte) string {
	switch c {
	case 'y':
		return "YAML"
	case 't':
		return "TOML"
	case 'j':
		return "JSON"
	case 'c':
		return "HCL"
	}
	return ""
}

func parseFlags(args []string) (*Options, bool, bool, []byte, error) {
	opts := &Options{}
	var formats []byte
	var invalid []byte
	showHelp := false
	showVersion := false

	for _, arg := range args {
		// Strip a single leading dash.
		s := arg
		if len(s) > 0 && s[0] == '-' {
			s = s[1:]
		}
		for i := 0; i < len(s); i++ {
			c := s[i]
			switch c {
			case 'y', 't', 'j', 'c':
				formats = append(formats, c)
			case 'r':
				formats = append(formats, 'j', 'y')
			case 'n':
				opts.NoConvert = true
			case 'e':
				opts.Escape = true
			case 'i':
				opts.Indent = true
			case 'k':
				opts.Keys = true
			case 'h':
				showHelp = true
			case 'v':
				showVersion = true
			default:
				invalid = append(invalid, c)
			}
		}
	}

	// Set from/to based on format chars
	opts.From = 'y'
	opts.To = 'j'
	if len(formats) == 1 {
		opts.From = formats[0]
	} else if len(formats) >= 2 {
		opts.From = formats[len(formats)-2]
		opts.To = formats[len(formats)-1]
	}
	opts.FromName = formatName(opts.From)
	opts.ToName = formatName(opts.To)

	return opts, showHelp, showVersion, invalid, nil
}

func main() {
	prog := os.Args[0]
	opts, showHelp, showVersion, invalid, _ := parseFlags(os.Args[1:])

	if showHelp {
		fmt.Fprintf(os.Stdout, usage, prog)
		os.Exit(0)
	}

	if len(invalid) > 0 {
		printUsage(os.Stderr, prog)
		// Format invalid chars separated by spaces
		buf := make([]byte, 0, len(invalid)*2)
		for i, c := range invalid {
			if i > 0 {
				buf = append(buf, ' ')
			}
			buf = append(buf, c)
		}
		fmt.Fprintf(os.Stderr, "\nError: invalid flags specified: %s\n", string(buf))
		os.Exit(1)
	}

	if showVersion {
		fmt.Println(version)
		os.Exit(0)
	}

	// Validate option constraints
	if opts.Indent && opts.To != 'j' && opts.To != 't' {
		printUsage(os.Stderr, prog)
		fmt.Fprintln(os.Stderr, "\nError: flag -i only valid for JSON or TOML output")
		os.Exit(1)
	}
	if opts.Escape && opts.To != 'j' {
		printUsage(os.Stderr, prog)
		fmt.Fprintln(os.Stderr, "\nError: flag -e only valid for JSON output")
		os.Exit(1)
	}
	if opts.Keys && opts.To != 'y' {
		printUsage(os.Stderr, prog)
		fmt.Fprintln(os.Stderr, "\nError: flag -k only valid for YAML output")
		os.Exit(1)
	}
	if opts.NoConvert && opts.From != 'y' && opts.From != 't' && opts.To != 'y' && opts.To != 't' {
		printUsage(os.Stderr, prog)
		fmt.Fprintln(os.Stderr, "\nError: flag -n only valid for YAML or TOML input/output")
		os.Exit(1)
	}

	input, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading stdin: %v\n", err)
		os.Exit(1)
	}

	var val Value
	// Parse
	switch opts.From {
	case 'y':
		val, err = DecodeYAML(input, opts)
	case 'j':
		val, err = DecodeJSON(input, opts)
	case 't':
		val, err = DecodeTOML(input, opts)
	case 'c':
		val, err = DecodeHCL(input, opts)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing %s: %s\n", opts.FromName, err.Error())
		os.Exit(1)
	}
	if val == nil && opts.From == 'y' && len(input) == 0 {
		// Empty YAML -> no output
		os.Exit(0)
	}

	// Encode
	var out []byte
	switch opts.To {
	case 'j':
		out, err = EncodeJSON(val, opts)
	case 'y':
		out, err = EncodeYAML(val, opts)
	case 't':
		out, err = EncodeTOML(val, opts)
	case 'c':
		out, err = EncodeHCL(val, opts)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error encoding %s: %s\n", opts.ToName, err.Error())
		os.Exit(1)
	}

	os.Stdout.Write(out)
}
EOF
echo "OK"

