// Number represents a parsed number that preserves its representation
// (e.g., whether it was int-like or float-like) for precise round-tripping.
type Number struct {
	// Src is the original textual representation (may be empty for
	// programmatic numbers, in which case F/I are used).
	Src string
	// IsFloat indicates whether this is a floating-point number.
	IsFloat bool
	// I stores integer-like numbers (if small enough).
	I int64
	// BigI stores integer-like numbers (if outside int64).
	BigI *big.Int
	// F stores floating-point values.
	F float64
}

// IsInt returns true if the number is integer-typed.
func (n Number) IsInt() bool { return !n.IsFloat }

// Float64 returns a float64 value for the number.
func (n Number) Float64() float64 {
	if n.IsFloat {
		return n.F
	}
	if n.BigI != nil {
		f, _ := new(big.Float).SetInt(n.BigI).Float64()
		return f
	}
	return float64(n.I)
}

// Int64 returns an int64 value if the number fits.
func (n Number) Int64() (int64, bool) {
	if n.IsFloat {
		return 0, false
	}
	if n.BigI != nil {
		if n.BigI.IsInt64() {
			return n.BigI.Int64(), true
		}
		return 0, false
	}
	return n.I, true
}

// NumberFromInt creates a Number from int64.
func NumberFromInt(i int64) Number {
	return Number{I: i}
}

// NumberFromFloat creates a Number from float64.
func NumberFromFloat(f float64) Number {
	return Number{IsFloat: true, F: f, Src: formatFloat(f)}
}

// NumberFromString parses a string into a Number.
func NumberFromString(s string) (Number, error) {
	if s == "" {
		return Number{}, fmt.Errorf("empty number")
	}
	if strings.ContainsAny(s, ".eE") || s == "Infinity" || s == "-Infinity" || s == "NaN" {
		// float
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return Number{}, err
		}
		return Number{IsFloat: true, F: f, Src: s}, nil
	}
	// integer
	i, err := strconv.ParseInt(s, 10, 64)
	if err == nil {
		return Number{I: i, Src: s}, nil
	}
	// Try big int
	bi := new(big.Int)
	_, ok := bi.SetString(s, 10)
	if ok {
		return Number{BigI: bi, Src: s}, nil
	}
	// fallback to float
	f, err2 := strconv.ParseFloat(s, 64)
	if err2 != nil {
		return Number{}, err
	}
	return Number{IsFloat: true, F: f, Src: s}, nil
}

// formatFloat produces the canonical JSON-like representation of a float.
func formatFloat(f float64) string {
	// Produce Go's default %g-style representation (like strconv.FormatFloat 'g', -1, 64)
	return strconv.FormatFloat(f, 'g', -1, 64)
