	if n.IsFloat {
		return formatFloat(n.F)
	}
	if n.BigI != nil {
		return n.BigI.String()
	}
	if n.Src != "" {
		return n.Src
	}
	return strconv.FormatInt(n.I, 10)
}

// String returns a general textual representation (like JSON).
func (n Number) String() string { return n.JSONString() }
