// DecodeJSON parses JSON into a Value, preserving map order.
func DecodeJSON(b []byte, _ *Options) (Value, error) {
	d := &jsonDecoder{src: b, pos: 0}
	d.skipWS()
	if d.pos >= len(d.src) {
		return nil, fmt.Errorf("unexpected end of JSON input")
	}
	v, err := d.decodeValue()
	if err != nil {
		return nil, err
	}
	d.skipWS()
	if d.pos < len(d.src) {
		c := d.src[d.pos]
		return nil, fmt.Errorf("invalid character %s after top-level value", quoteChar(c))
	}
	return v, nil
}

func quoteChar(c byte) string {
	if c >= 0x20 && c < 0x7f {
		return "'" + string(c) + "'"
	}
	return fmt.Sprintf("'\\x%02x'", c)
}

type jsonDecoder struct {
	src []byte
	pos int
}

