	for i < len(s) {
		c := s[i]
		if c < utf8.RuneSelf {
			if c == '\\' {
				sb.WriteString(`\\`)
				i++
				continue
			}
			if c == '"' {
				sb.WriteString(`\"`)
				i++
				continue
			}
			// Always escape control chars and HTML if requested.
			if e.escape && (c == '<' || c == '>' || c == '&') {
				sb.WriteString(`\u00`)
				sb.WriteByte(hexDigit(c >> 4))
				sb.WriteByte(hexDigit(c & 0xf))
				i++
				continue
			}
			if c < 0x20 {
				switch c {
				case '\n':
					sb.WriteString(`\n`)
				case '\r':
					sb.WriteString(`\r`)
				case '\t':
					sb.WriteString(`\t`)
				case '\b':
					sb.WriteString(`\b`)
				case '\f':
					sb.WriteString(`\f`)
				default:
					sb.WriteString(`\u00`)
					sb.WriteByte(hexDigit(c >> 4))
					sb.WriteByte(hexDigit(c & 0xf))
				}
				i++
				continue
			}
			sb.WriteByte(c)
			i++
			continue
		}
		// Multi-byte rune
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			sb.WriteString(`\ufffd`)
			i++
			continue
		}
		// Escape U+2028 and U+2029 if HTML escape is on
		if e.escape && (r == 0x2028 || r == 0x2029) {
			sb.WriteString(`\u202`)
			if r == 0x2028 {
				sb.WriteByte('8')
			} else {
				sb.WriteByte('9')
			}
			i += size
			continue
		}
		sb.WriteString(s[i : i+size])
		i += size
	}
	sb.WriteByte('"')
	e.buf.WriteString(sb.String())
}

func hexDigit(b byte) byte {
	if b < 10 {
		return '0' + b
	}
	return 'a' + b - 10
