// formatFloatJSON matches Go's encoding/json float formatting.
func formatFloatJSON(f float64) string {
	// Mirror Go's encoding/json handling: prefer 'e' for large/small, else 'f'.
	abs := f
	if abs < 0 {
		abs = -abs
	}
	fmt_ := byte('f')
	if abs != 0 {
		if abs < 1e-6 || abs >= 1e21 {
			fmt_ = 'e'
		}
	}
	s := strconv.FormatFloat(f, fmt_, -1, 64)
	if fmt_ == 'e' {
		// Normalize exponent: Go's encoding/json removes leading zeros in exponent.
		// strconv.FormatFloat may produce "1e+09"; we want "1e+9".
		n := len(s)
		if n >= 4 && s[n-4] == 'e' && s[n-3] == '-' && s[n-2] == '0' {
			s = s[:n-2] + s[n-1:]
		} else if n >= 4 && s[n-4] == 'e' && s[n-3] == '+' && s[n-2] == '0' {
			s = s[:n-2] + s[n-1:]
		}
	}
	return s
}

func isInf(f float64, sign int) bool {
	return (sign >= 0 && f > 1.7976931348623157e+308) || (sign <= 0 && f < -1.7976931348623157e+308)
}

func isNaN(f float64) bool {
	return f != f
}
