func (d *jsonDecoder) decodeValue() (Value, error) {
	d.skipWS()
	if d.pos >= len(d.src) {
		return nil, fmt.Errorf("unexpected end of JSON input")
	}
	c := d.src[d.pos]
	switch {
	case c == '{':
		return d.decodeObject()
	case c == '[':
		return d.decodeArray()
	case c == '"':
		return d.decodeString()
	case c == 't' || c == 'f':
		return d.decodeBool()
	case c == 'n':
		return d.decodeNull()
	case c == '-' || (c >= '0' && c <= '9'):
		return d.decodeNumber()
	}
	return nil, fmt.Errorf("invalid character %s looking for beginning of value", quoteChar(c))
