		if d.pos >= len(d.src) || d.src[d.pos] != ':' {
			if d.pos < len(d.src) {
				return nil, fmt.Errorf("invalid character %s after object key", quoteChar(d.src[d.pos]))
			}
			return nil, fmt.Errorf("unexpected end of JSON input")
		}
		d.pos++
		val, err := d.decodeValue()
		if err != nil {
			return nil, err
		}
		m.Set(key.(string), val)
		d.skipWS()
		if d.pos >= len(d.src) {
			return nil, fmt.Errorf("unexpected end of JSON input")
		}
		c := d.src[d.pos]
		if c == ',' {
