func (d *jsonDecoder) decodeNull() (Value, error) {
	if bytes.HasPrefix(d.src[d.pos:], []byte("null")) {
		d.pos += 4
		return nil, nil
	}
	return nil, fmt.Errorf("invalid character %s in literal", quoteChar(d.src[d.pos]))
}

