	for d.pos < len(d.src) {
		c := d.src[d.pos]
		if c >= '0' && c <= '9' {
			d.pos++
		} else {
			break
		}
	}
	if d.pos < len(d.src) && d.src[d.pos] == '.' {
		d.pos++
		for d.pos < len(d.src) {
