// EncodeJSON encodes a Value as JSON.
func EncodeJSON(v Value, opts *Options) ([]byte, error) {
	var buf bytes.Buffer
	enc := &jsonEncoder{buf: &buf, escape: opts != nil && opts.Escape, indent: opts != nil && opts.Indent, noConv: opts != nil && opts.NoConvert}
	if err := enc.encode(v, 0); err != nil {
