				case '\b':
					sb.WriteString(`\b`)
				case '\f':
					sb.WriteString(`\f`)
				default:
					sb.WriteString(`\u00`)
					sb.WriteByte(hexDigit(c >> 4))
					sb.WriteByte(hexDigit(c & 0xf))
