// DecodeYAML parses YAML input into a Value, preserving map order.
func DecodeYAML(b []byte, opts *Options) (Value, error) {
	noConv := opts != nil && opts.NoConvert
	// Normalize line endings and strip BOM.
	if bytes.HasPrefix(b, []byte{0xEF, 0xBB, 0xBF}) {
		b = b[3:]
	}
	b = bytes.ReplaceAll(b, []byte("\r\n"), []byte("\n"))
	b = bytes.ReplaceAll(b, []byte("\r"), []byte("\n"))

	p := &yamlParser{
		src:    b,
		noConv: noConv,
		anchor: map[string]Value{},
	}
	// Collect lines for the line-oriented block parser.
	p.prepare()
	if len(p.lines) == 0 {
		return nil, nil
	}
	// Strip leading doc separator and directives
	p.skipDocHeader()
	if p.isAtEnd() {
		return nil, nil
	}
	v, err := p.parseNode(0)
	if err != nil {
		return nil, err
	}
	return v, nil
}

type yamlLine struct {
	raw    string // line without trailing newline or comment
	indent int
	empty  bool
	lineNo int
}

type yamlParser struct {
	src    []byte
	lines  []yamlLine
	idx    int
	noConv bool
	anchor map[string]Value
}

func (p *yamlParser) prepare() {
	raw := string(p.src)
	lines := strings.Split(raw, "\n")
	for i, l := range lines {
		if i == len(lines)-1 && l == "" {
			// trailing newline -> last empty
			continue
		}
		yl := yamlLine{raw: l, lineNo: i + 1}
		trimmed := strings.TrimLeft(l, " ")
		yl.indent = len(l) - len(trimmed)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			yl.empty = true
		}
		p.lines = append(p.lines, yl)
	}
}

func (p *yamlParser) skipDocHeader() {
	for p.idx < len(p.lines) {
		l := p.lines[p.idx]
		t := strings.TrimLeft(l.raw, " ")
		if t == "---" || strings.HasPrefix(t, "%") {
			p.idx++
			continue
		}
		if l.empty {
			p.idx++
			continue
		}
		break
	}
}

func (p *yamlParser) isAtEnd() bool {
	for p.idx < len(p.lines) {
		l := p.lines[p.idx]
		t := strings.TrimLeft(l.raw, " ")
		if t == "..." {
			return true
		}
		if l.empty {
			p.idx++
			continue
		}
		return false
	}
	return true
}

// parseNode parses a YAML node starting at the current line with given minimum indent.
func (p *yamlParser) parseNode(minIndent int) (Value, error) {
	// Skip blank/comment lines
	for p.idx < len(p.lines) && p.lines[p.idx].empty {
		p.idx++
	}
	if p.idx >= len(p.lines) {
		return nil, nil
	}
	l := p.lines[p.idx]
	if l.indent < minIndent {
		return nil, nil
	}
	trimmed := strings.TrimLeft(l.raw, " ")
	// Handle anchors/tags and aliases at beginning
	var anchor string
	var tag string
	rest := trimmed
	for {
		if strings.HasPrefix(rest, "&") {
			// anchor name
			end := strings.IndexAny(rest[1:], " \t")
			if end < 0 {
				anchor = rest[1:]
				rest = ""
			} else {
				anchor = rest[1 : 1+end]
				rest = strings.TrimLeft(rest[1+end:], " ")
			}
			continue
		}
		if strings.HasPrefix(rest, "!") {
			end := strings.IndexAny(rest, " \t")
			if end < 0 {
				tag = rest
				rest = ""
			} else {
				tag = rest[:end]
				rest = strings.TrimLeft(rest[end:], " ")
			}
			continue
		}
		break
	}
	_ = tag
	// Alias
	if strings.HasPrefix(rest, "*") {
		end := len(rest)
		for i := 1; i < len(rest); i++ {
			c := rest[i]
			if c == ' ' || c == '\t' || c == ',' || c == ']' || c == '}' {
				end = i
				break
			}
		}
		name := rest[1:end]
		v, ok := p.anchor[name]
		if !ok {
			return nil, fmt.Errorf("unknown anchor '%s' referenced", name)
		}
		p.idx++
		if anchor != "" {
			p.anchor[anchor] = v
		}
		return v, nil
	}
	// Block sequence
	if rest == "-" || strings.HasPrefix(rest, "- ") {
		return p.parseBlockSeq(l.indent, anchor)
	}
	// Flow collection or mapping
	// Check if this line is a mapping key
	if mappingLine, keyEnd := detectMappingKey(rest); mappingLine {
		return p.parseBlockMap(l.indent, anchor, keyEnd)
	}
	// Otherwise, scalar
	v, err := p.parseScalar(rest, l.indent)
	if err != nil {
		return nil, err
	}
	if anchor != "" {
		p.anchor[anchor] = v
	}
	return v, nil
}

// detectMappingKey returns true if the content starts a block mapping.
// It finds the position of the colon that ends the key.
func detectMappingKey(s string) (bool, int) {
	// Complex flow syntax: find colon that ends the key
	// Must be followed by space or EOL
	if strings.HasPrefix(s, "? ") || s == "?" {
		// explicit mapping key
		return true, -1 // special sentinel for explicit key
	}
	// Skip quoted strings, flow collections
	i := 0
	n := len(s)
	for i < n {
		c := s[i]
		switch c {
		case '"':
			j := i + 1
			for j < n && s[j] != '"' {
				if s[j] == '\\' && j+1 < n {
					j += 2
					continue
				}
				j++
			}
			if j >= n {
				return false, -1
			}
			i = j + 1
		case '\'':
			j := i + 1
			for j < n {
				if s[j] == '\'' {
					if j+1 < n && s[j+1] == '\'' {
						j += 2
						continue
					}
					break
				}
				j++
			}
			if j >= n {
				return false, -1
			}
			i = j + 1
		case '[', '{':
			depth := 1
			j := i + 1
			for j < n && depth > 0 {
				switch s[j] {
				case '[', '{':
					depth++
				case ']', '}':
					depth--
				case '"':
					k := j + 1
					for k < n && s[k] != '"' {
						if s[k] == '\\' && k+1 < n {
							k += 2
							continue
						}
						k++
					}
					j = k
				case '\'':
					k := j + 1
					for k < n {
						if s[k] == '\'' {
							if k+1 < n && s[k+1] == '\'' {
								k += 2
								continue
							}
							break
						}
						k++
					}
					j = k
				}
				j++
			}
			i = j
		case ':':
			// Check if followed by space or EOL
			if i+1 == n || s[i+1] == ' ' || s[i+1] == '\t' {
				return true, i
			}
			i++
		case '#':
			return false, -1
		default:
			i++
		}
	}
	return false, -1
}

// parseBlockSeq parses a block sequence starting at the given indent.
func (p *yamlParser) parseBlockSeq(indent int, anchor string) (Value, error) {
	var arr []Value
	for p.idx < len(p.lines) {
		l := p.lines[p.idx]
		if l.empty {
			p.idx++
			continue
		}
		if l.indent != indent {
			break
		}
		trimmed := strings.TrimLeft(l.raw, " ")
		if trimmed != "-" && !strings.HasPrefix(trimmed, "- ") {
			break
		}
		// Prepare rest after dash
		if trimmed == "-" {
			// Element is on next line(s)
			p.idx++
			v, err := p.parseNode(indent + 1)
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
		} else {
			// "- <content>"
			rest := trimmed[2:]
			// Compute new indent = indent + 2 (dash+space)
			newIndent := indent + 2
			for i := 2; i < len(trimmed) && trimmed[i] == ' '; i++ {
				newIndent++
			}
			rest = strings.TrimLeft(rest, " ")
			// Replace the line temporarily with the rest, so parseNode picks it up at newIndent
			saved := p.lines[p.idx]
			p.lines[p.idx] = yamlLine{raw: strings.Repeat(" ", newIndent) + rest, indent: newIndent, lineNo: saved.lineNo}
			// Check if it's a nested sequence or mapping
			if mapped, _ := detectMappingKey(rest); mapped {
				v, err := p.parseBlockMap(newIndent, "", 0)
				if err != nil {
					return nil, err
				}
				arr = append(arr, v)
			} else if rest == "-" || strings.HasPrefix(rest, "- ") {
				v, err := p.parseBlockSeq(newIndent, "")
				if err != nil {
					return nil, err
				}
				arr = append(arr, v)
			} else {
				// Scalar
				v, err := p.parseScalar(rest, newIndent)
				if err != nil {
					return nil, err
				}
				if p.idx < len(p.lines) && p.lines[p.idx] == (yamlLine{raw: strings.Repeat(" ", newIndent) + rest, indent: newIndent, lineNo: saved.lineNo}) {
					p.idx++
				}
				p.lines[p.idx-1] = saved
				arr = append(arr, v)
				continue
			}
			p.lines[p.idx-1] = saved
		}
	}
	if anchor != "" {
		p.anchor[anchor] = arr
	}
	return arr, nil
}

// parseBlockMap parses a block mapping.
func (p *yamlParser) parseBlockMap(indent int, anchor string, _ int) (Value, error) {
	m := NewOrderedMap()
	for p.idx < len(p.lines) {
		l := p.lines[p.idx]
		if l.empty {
			p.idx++
			continue
		}
		if l.indent != indent {
			break
		}
		trimmed := strings.TrimLeft(l.raw, " ")
		// Check for explicit key `? key`
		if trimmed == "?" || strings.HasPrefix(trimmed, "? ") {
			var keyContent string
			if trimmed == "?" {
				p.idx++
				k, err := p.parseNode(indent + 1)
				if err != nil {
					return nil, err
				}
				// Now expect `: value` or `:`
				if p.idx >= len(p.lines) {
					m.Set(k, nil)
					break
				}
				l2 := p.lines[p.idx]
				t2 := strings.TrimLeft(l2.raw, " ")
				if l2.indent == indent && (t2 == ":" || strings.HasPrefix(t2, ": ")) {
					var rest string
					if t2 == ":" {
						p.idx++
						v, err := p.parseNode(indent + 1)
						if err != nil {
							return nil, err
						}
						m.Set(k, v)
					} else {
						rest = strings.TrimLeft(t2[1:], " ")
						// Replace line with rest at indent+2
						newIndent := indent + 2
						saved := p.lines[p.idx]
						p.lines[p.idx] = yamlLine{raw: strings.Repeat(" ", newIndent) + rest, indent: newIndent, lineNo: saved.lineNo}
						v, err := p.parseScalar(rest, newIndent)
						if err != nil {
							return nil, err
						}
						p.lines[p.idx] = saved
						p.idx++
						m.Set(k, v)
					}
				}
				continue
			}
			_ = keyContent
		}
		// Normal key: detect colon
		ok, keyEnd := detectMappingKey(trimmed)
		if !ok {
			break
		}
		keyStr := strings.TrimSpace(trimmed[:keyEnd])
		rest := strings.TrimLeft(trimmed[keyEnd+1:], " ")
		// Key parsing: try parsing with scalar rules on key
		key, err := p.parseKey(keyStr)
		if err != nil {
			return nil, err
		}
		if rest == "" || strings.HasPrefix(rest, "#") {
			// Value on next line
			p.idx++
			v, err := p.parseNode(indent + 1)
			if err != nil {
				return nil, err
			}
			// Handle merge key <<
			if ks, isStr := key.(string); isStr && ks == "<<" {
				mergeInto(m, v)
				continue
			}
			m.Set(key, v)
		} else {
			// Value on same line
			p.idx++
			if rest == "|" || rest == ">" || strings.HasPrefix(rest, "|") || strings.HasPrefix(rest, ">") {
				// Block scalar - parse from following lines
				v, err := p.parseBlockScalar(rest, indent)
				if err != nil {
					return nil, err
				}
				m.Set(key, v)
			} else if rest == "-" || strings.HasPrefix(rest, "- ") {
				// sequence on same line - unusual but possible
				p.idx--
				// use a virtual position by putting it on the next index with adjusted indent
				saved := p.lines[p.idx]
				newIndent := indent + 2
				p.lines[p.idx] = yamlLine{raw: strings.Repeat(" ", newIndent) + rest, indent: newIndent, lineNo: saved.lineNo}
				v, err := p.parseBlockSeq(newIndent, "")
				if err != nil {
					return nil, err
				}
				p.lines[p.idx-1] = saved
				m.Set(key, v)
			} else {
				v, err := p.parseScalar(rest, indent+2)
				if err != nil {
					return nil, err
				}
				if ks, isStr := key.(string); isStr && ks == "<<" {
					mergeInto(m, v)
					continue
				}
				m.Set(key, v)
			}
		}
	}
	if anchor != "" {
		p.anchor[anchor] = m
	}
	return m, nil
}

// mergeInto merges contents of src map(s) into dst (for << keys), preserving existing keys.
func mergeInto(dst *OrderedMap, src Value) {
	switch s := src.(type) {
	case *OrderedMap:
		for _, p := range s.Pairs {
			if _, ok := dst.Get(p.Key); !ok {
				dst.Set(p.Key, p.Value)
			}
		}
	case []Value:
		for _, item := range s {
			mergeInto(dst, item)
		}
	}
}

func (p *yamlParser) parseKey(s string) (Value, error) {
	// YAML keys are typically scalars. Try string identity for quoted,
	// numeric parsing for plain.
	return p.parseScalarInline(s), nil
}

// parseScalar parses a scalar value starting with the given text; if block
// scalar indicator, consumes following lines.
func (p *yamlParser) parseScalar(s string, baseIndent int) (Value, error) {
	s = strings.TrimRight(s, " \t")
	if s == "|" || s == ">" || strings.HasPrefix(s, "|") || strings.HasPrefix(s, ">") {
		return p.parseBlockScalar(s, baseIndent-2)
	}
	// Handle flow collections.
	if strings.HasPrefix(s, "{") || strings.HasPrefix(s, "[") {
		return p.parseFlow(s)
	}
	// Handle quoted scalars spanning multiple lines: simple: assume single-line.
	if strings.HasPrefix(s, "\"") {
		v, _, err := parseDoubleQuoted(s, 0)
		return v, err
	}
	if strings.HasPrefix(s, "'") {
		v, _, err := parseSingleQuoted(s, 0)
		return v, err
	}
	// Plain scalar: strip trailing comment
	s = stripComment(s)
	return p.parseScalarInline(s), nil
}

// parseScalarInline handles plain scalars (applying YAML type coercion).
func (p *yamlParser) parseScalarInline(s string) Value {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil
	}
	// Null
	switch s {
	case "~", "null", "Null", "NULL":
		return nil
	case "true", "True", "TRUE":
		return true
	case "false", "False", "FALSE":
		return false
	}
	// Numbers
	// Hex
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
		if i, err := strconv.ParseInt(s[2:], 16, 64); err == nil {
			return Number{I: i, Src: strconv.FormatInt(i, 10)}
		}
	}
	// Octal
	if strings.HasPrefix(s, "0o") || strings.HasPrefix(s, "0O") {
		if i, err := strconv.ParseInt(s[2:], 8, 64); err == nil {
			return Number{I: i, Src: strconv.FormatInt(i, 10)}
		}
	}
	// Inf/NaN
	switch s {
	case ".inf", ".Inf", ".INF":
		if p.noConv {
			return Number{IsFloat: true, F: math.MaxFloat64, Src: formatFloat(math.MaxFloat64)}
		}
		return "Infinity"
	case "-.inf", "-.Inf", "-.INF":
		if p.noConv {
			return Number{IsFloat: true, F: -math.MaxFloat64, Src: formatFloat(-math.MaxFloat64)}
		}
		return "-Infinity"
	case ".nan", ".NaN", ".NAN":
		if p.noConv {
			return nil
		}
		return "NaN"
	case "+.inf", "+.Inf", "+.INF":
		if p.noConv {
			return Number{IsFloat: true, F: math.MaxFloat64, Src: formatFloat(math.MaxFloat64)}
		}
		return "Infinity"
	}
	// Try as integer/big int/float
	if n, err := NumberFromString(s); err == nil {
		return n
	}
	return s
}

// parseBlockScalar handles "|" and ">" block scalars.
func (p *yamlParser) parseBlockScalar(header string, parentIndent int) (Value, error) {
	style := header[0] // '|' or '>'
	chomp := byte(0)   // default clip
	// Parse header like "|-" "|+" ">2"
	for i := 1; i < len(header); i++ {
		c := header[i]
		if c == '-' || c == '+' {
			chomp = c
		}
	}
	var lines []string
	indent := -1
	for p.idx < len(p.lines) {
		l := p.lines[p.idx]
		if l.raw == "" {
			lines = append(lines, "")
			p.idx++
			continue
		}
		if l.indent <= parentIndent && !l.empty {
			break
		}
		if indent == -1 {
			indent = l.indent
		}
		if l.indent < indent && !l.empty {
			break
		}
		content := l.raw
		if len(content) >= indent {
			content = content[indent:]
		}
		lines = append(lines, content)
		p.idx++
	}
	// Apply chomping
	trailing := 0
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trailing++
	}
	var out string
	if style == '|' {
		out = strings.Join(lines, "\n")
		if chomp == '+' {
			out += strings.Repeat("\n", trailing+1)
		} else if chomp == 0 {
			out += "\n"
		}
	} else {
		// folded: newlines between non-blank lines become spaces; blank lines become \n
		var sb strings.Builder
		for i, l := range lines {
			if i == 0 {
				sb.WriteString(l)
				continue
			}
			prev := lines[i-1]
			if prev == "" || l == "" {
				sb.WriteString("\n")
			} else {
				sb.WriteString(" ")
			}
			sb.WriteString(l)
		}
		out = sb.String()
		if chomp == '+' {
			out += strings.Repeat("\n", trailing+1)
		} else if chomp == 0 {
			out += "\n"
		}
	}
	return out, nil
}

func stripComment(s string) string {
	inDouble := false
	inSingle := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inDouble {
			if c == '\\' && i+1 < len(s) {
				i++
				continue
			}
			if c == '"' {
				inDouble = false
			}
		} else if inSingle {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
					continue
				}
				inSingle = false
			}
		} else {
			switch c {
			case '"':
				inDouble = true
			case '\'':
				inSingle = true
			case '#':
				if i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') {
					return strings.TrimRight(s[:i], " \t")
				}
			}
		}
	}
	return strings.TrimRight(s, " \t")
}

// parseDoubleQuoted parses a double-quoted YAML string starting at idx.
func parseDoubleQuoted(s string, idx int) (string, int, error) {
	if s[idx] != '"' {
		return "", idx, fmt.Errorf("expected double quote")
	}
	var sb strings.Builder
	i := idx + 1
	for i < len(s) {
		c := s[i]
		if c == '"' {
			return sb.String(), i + 1, nil
		}
		if c == '\\' {
			i++
			if i >= len(s) {
				return "", i, fmt.Errorf("unterminated double-quoted string")
			}
			esc := s[i]
			switch esc {
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case '/':
				sb.WriteByte('/')
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
				sb.WriteByte('\t')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case '0':
				sb.WriteByte(0)
			case 'a':
				sb.WriteByte(7)
			case 'v':
				sb.WriteByte(0xb)
			case 'e':
				sb.WriteByte(0x1b)
			case ' ':
				sb.WriteByte(' ')
			case 'N':
				sb.WriteRune(0x85)
			case '_':
				sb.WriteRune(0xa0)
			case 'x':
				if i+2 < len(s) {
					hex := s[i+1 : i+3]
					r, err := strconv.ParseUint(hex, 16, 32)
					if err == nil {
						sb.WriteRune(rune(r))
						i += 2
					}
				}
			case 'u':
				if i+4 < len(s) {
					hex := s[i+1 : i+5]
					r, err := strconv.ParseUint(hex, 16, 32)
					if err == nil {
						sb.WriteRune(rune(r))
						i += 4
					}
				}
			default:
				sb.WriteByte(esc)
			}
			i++
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return "", i, fmt.Errorf("unterminated double-quoted string")
}

func parseSingleQuoted(s string, idx int) (string, int, error) {
	if s[idx] != '\'' {
		return "", idx, fmt.Errorf("expected single quote")
	}
	var sb strings.Builder
	i := idx + 1
	for i < len(s) {
		c := s[i]
		if c == '\'' {
			if i+1 < len(s) && s[i+1] == '\'' {
				sb.WriteByte('\'')
				i += 2
				continue
			}
			return sb.String(), i + 1, nil
		}
		sb.WriteByte(c)
		i++
	}
	return "", i, fmt.Errorf("unterminated single-quoted string")
}

// parseFlow parses a YAML flow collection (starts with '{' or '[').
func (p *yamlParser) parseFlow(s string) (Value, error) {
	// Flow might span multiple lines in YAML, but for simplicity assume single line.
	v, _, err := parseFlowExpr(s, 0)
	if err != nil {
		return nil, err
	}
	p.idx++
	return v, nil
}

func parseFlowExpr(s string, idx int) (Value, int, error) {
	idx = skipFlowWS(s, idx)
	if idx >= len(s) {
		return nil, idx, fmt.Errorf("unexpected end of flow")
	}
	c := s[idx]
	switch {
	case c == '[':
		return parseFlowSeq(s, idx)
	case c == '{':
		return parseFlowMap(s, idx)
	case c == '"':
		str, end, err := parseDoubleQuoted(s, idx)
		if err != nil {
			return nil, end, err
		}
		return str, end, nil
	case c == '\'':
		str, end, err := parseSingleQuoted(s, idx)
		if err != nil {
			return nil, end, err
		}
		return str, end, nil
	default:
		// plain scalar until , ] }
		end := idx
		for end < len(s) && s[end] != ',' && s[end] != ']' && s[end] != '}' {
			if s[end] == ':' && (end+1 == len(s) || s[end+1] == ' ' || s[end+1] == ',' || s[end+1] == ']' || s[end+1] == '}') {
				break
			}
			end++
		}
		text := strings.TrimSpace(s[idx:end])
		p := &yamlParser{}
		return p.parseScalarInline(text), end, nil
	}
}

func skipFlowWS(s string, idx int) int {
	for idx < len(s) {
		c := s[idx]
		if c == ' ' || c == '\t' || c == '\n' {
			idx++
			continue
		}
		break
	}
	return idx
}

func parseFlowSeq(s string, idx int) ([]Value, int, error) {
	if s[idx] != '[' {
		return nil, idx, fmt.Errorf("expected [")
	}
	idx++
	var arr []Value
	idx = skipFlowWS(s, idx)
	if idx < len(s) && s[idx] == ']' {
		return arr, idx + 1, nil
	}
	for {
		v, ni, err := parseFlowExpr(s, idx)
		if err != nil {
			return nil, ni, err
		}
		arr = append(arr, v)
		idx = skipFlowWS(s, ni)
		if idx >= len(s) {
			return nil, idx, fmt.Errorf("unexpected end in flow sequence")
		}
		if s[idx] == ',' {
			idx++
			idx = skipFlowWS(s, idx)
			if idx < len(s) && s[idx] == ']' {
				return arr, idx + 1, nil
			}
			continue
		}
		if s[idx] == ']' {
			return arr, idx + 1, nil
		}
		return nil, idx, fmt.Errorf("invalid flow sequence")
	}
}

func parseFlowMap(s string, idx int) (*OrderedMap, int, error) {
	if s[idx] != '{' {
		return nil, idx, fmt.Errorf("expected {")
	}
	idx++
	m := NewOrderedMap()
	idx = skipFlowWS(s, idx)
	if idx < len(s) && s[idx] == '}' {
		return m, idx + 1, nil
	}
	for {
		key, ni, err := parseFlowExpr(s, idx)
		if err != nil {
			return nil, ni, err
		}
		idx = skipFlowWS(s, ni)
		if idx >= len(s) {
			return nil, idx, fmt.Errorf("unexpected end in flow map")
		}
		if s[idx] != ':' {
			// key without value
			m.Set(key, nil)
		} else {
			idx++
			idx = skipFlowWS(s, idx)
			var val Value
			if idx < len(s) && s[idx] != ',' && s[idx] != '}' {
				v, ni2, err := parseFlowExpr(s, idx)
				if err != nil {
					return nil, ni2, err
				}
				val = v
				idx = skipFlowWS(s, ni2)
			}
			m.Set(key, val)
		}
		if idx >= len(s) {
			return nil, idx, fmt.Errorf("unexpected end in flow map")
		}
		if s[idx] == ',' {
			idx++
			idx = skipFlowWS(s, idx)
			if idx < len(s) && s[idx] == '}' {
				return m, idx + 1, nil
			}
			continue
		}
		if s[idx] == '}' {
			return m, idx + 1, nil
		}
		return nil, idx, fmt.Errorf("invalid flow map")
	}
}

// ---- YAML Encoder ----

// EncodeYAML encodes a Value as YAML.
func EncodeYAML(v Value, opts *Options) ([]byte, error) {
	noConv := opts != nil && opts.NoConvert
	parseKeys := opts != nil && opts.Keys
	var buf bytes.Buffer
	enc := &yamlEncoder{buf: &buf, noConv: noConv, parseKeys: parseKeys}
	err := enc.encodeRoot(v)
	return buf.Bytes(), err
}

type yamlEncoder struct {
	buf       *bytes.Buffer
	noConv    bool
	parseKeys bool
}

func (e *yamlEncoder) encodeRoot(v Value) error {
	if v == nil {
		e.buf.WriteString("null\n")
		return nil
	}
	switch x := v.(type) {
	case *OrderedMap:
		if len(x.Pairs) == 0 {
			e.buf.WriteString("{}\n")
			return nil
		}
		return e.encodeMap(x, 0)
	case []Value:
		if len(x) == 0 {
			e.buf.WriteString("[]\n")
			return nil
		}
		return e.encodeSeq(x, 0)
	default:
		s := e.scalarString(v)
		e.buf.WriteString(s)
		e.buf.WriteByte('\n')
		return nil
	}
}

func (e *yamlEncoder) indent(depth int) {
	for i := 0; i < depth; i++ {
		e.buf.WriteString("  ")
	}
}

func (e *yamlEncoder) encodeMap(m *OrderedMap, depth int) error {
	for _, p := range m.Pairs {
		e.indent(depth)
		keyStr, isComplex := e.encodeKey(p.Key)
		if isComplex {
			// explicit key
			e.buf.WriteString("? ")
			e.buf.WriteString(keyStr)
			e.buf.WriteByte('\n')
			e.indent(depth)
			e.buf.WriteString(":")
		} else {
			e.buf.WriteString(keyStr)
			e.buf.WriteByte(':')
		}
		if err := e.encodeChild(p.Value, depth); err != nil {
			return err
		}
	}
	return nil
}

func (e *yamlEncoder) encodeSeq(a []Value, depth int) error {
	for _, v := range a {
		e.indent(depth)
		e.buf.WriteString("-")
		if err := e.encodeChild(v, depth); err != nil {
			return err
		}
	}
	return nil
}

func (e *yamlEncoder) encodeChild(v Value, depth int) error {
	switch x := v.(type) {
	case nil:
		e.buf.WriteByte('\n')
	case *OrderedMap:
		if len(x.Pairs) == 0 {
			e.buf.WriteString(" {}\n")
			return nil
		}
		e.buf.WriteByte('\n')
		return e.encodeMap(x, depth+1)
	case []Value:
		if len(x) == 0 {
			e.buf.WriteString(" []\n")
			return nil
		}
		e.buf.WriteByte('\n')
		return e.encodeSeq(x, depth+1)
	default:
		s := e.scalarYAML(v, depth+1)
		e.buf.WriteString(" ")
		e.buf.WriteString(s)
		if !strings.HasSuffix(s, "\n") {
			e.buf.WriteByte('\n')
		}
	}
	return nil
}

// encodeKey returns the representation of a key and whether it's a complex key.
func (e *yamlEncoder) encodeKey(k Value) (string, bool) {
	switch kv := k.(type) {
	case string:
		if e.parseKeys {
			// Try to parse as numeric/bool/etc.
			if kv == "" {
				return "''", false
			}
		}
		return yamlQuoteKey(kv), false
	case Number:
		return kv.JSONString(), false
	case bool:
		if kv {
			return "true", false
		}
		return "false", false
	case *OrderedMap, []Value:
		// Complex key - render inline or explicit
		var sb strings.Builder
		enc := &yamlEncoder{buf: &bytesBufferAdapter{sb: &sb}, noConv: e.noConv, parseKeys: e.parseKeys}
		switch x := kv.(type) {
		case *OrderedMap:
			_ = enc.encodeMap(x, 0)
		case []Value:
			_ = enc.encodeSeq(x, 0)
		}
		return strings.TrimRight(sb.String(), "\n"), true
	default:
		return fmt.Sprintf("%v", k), false
	}
}

// bytesBufferAdapter wraps a strings.Builder to look like a *bytes.Buffer for our purposes.
type bytesBufferAdapter struct{ sb *strings.Builder }

func (b *bytesBufferAdapter) Write(p []byte) (int, error)   { return b.sb.Write(p) }
func (b *bytesBufferAdapter) WriteString(s string) (int, error) { return b.sb.WriteString(s) }
func (b *bytesBufferAdapter) WriteByte(c byte) error             { return b.sb.WriteByte(c) }
func (b *bytesBufferAdapter) WriteRune(r rune) (int, error)      { return b.sb.WriteRune(r) }
func (b *bytesBufferAdapter) Bytes() []byte                       { return []byte(b.sb.String()) }
func (b *bytesBufferAdapter) Len() int                            { return b.sb.Len() }

// scalarYAML encodes a scalar for YAML output at a given depth.
func (e *yamlEncoder) scalarYAML(v Value, depth int) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case bool:
		if x {
			return "true"
		}
		return "false"
	case string:
		return yamlQuoteString(x, depth)
	case Number:
		if x.IsFloat {
			f := x.F
			if isNaN(f) {
				if e.noConv {
					return ".nan"
				}
				return "NaN"
			}
			if isInf(f, 1) {
				if e.noConv {
					return ".inf"
				}
				return "Infinity"
			}
			if isInf(f, -1) {
				if e.noConv {
					return "-.inf"
				}
				return "-Infinity"
			}
			return yamlFormatFloat(f)
		}
		return x.JSONString()
	}
	return fmt.Sprintf("%v", v)
}

func (e *yamlEncoder) scalarString(v Value) string {
	return e.scalarYAML(v, 0)
}

// yamlFormatFloat produces yaml.v3-like float formatting:
//   - Integers stay with ".0" or "e+".
//   - e.g. 1.5 -> "1.5", 1.0 -> "1.0", 1e5 -> "100000.0" no wait, observed "100000.0"
func yamlFormatFloat(f float64) string {
	// Prefer %g with -1 precision, but ensure a decimal or exponent is present.
	s := strconv.FormatFloat(f, 'g', -1, 64)
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	// Normalize "1e+10" -> "1e+10" (already), but yaml.v3 emits "1.5e+10".
	return s
}

// yamlQuoteKey returns a YAML-safe key representation.
func yamlQuoteKey(s string) string {
	return yamlQuoteString(s, 0)
}

// yamlQuoteString returns a YAML-safe string representation, choosing the
// best style based on the content.
func yamlQuoteString(s string, depth int) string {
	if s == "" {
		return "\"\""
	}
	// Contains newline -> literal block style
	if strings.Contains(s, "\n") {
		return yamlLiteralBlock(s, depth)
	}
	// Check plain-safe
	if isYAMLPlainSafe(s) {
		return s
	}
	// Single-quote safe (no control chars, no single quote issues)
	if canSingleQuote(s) {
		return "'" + strings.ReplaceAll(s, "'", "''") + "'"
	}
	// Double quote
	return doubleQuoteYAML(s)
}

func canSingleQuote(s string) bool {
	for _, r := range s {
		if r < 0x20 || r == 0x7f {
			return false
		}
	}
	return true
}

func isYAMLPlainSafe(s string) bool {
	if s == "" {
		return false
	}
	// Reserved words/values
	switch s {
	case "null", "Null", "NULL", "~",
		"true", "True", "TRUE",
		"false", "False", "FALSE",
		"yes", "Yes", "YES",
		"no", "No", "NO",
		"on", "On", "ON",
		"off", "Off", "OFF",
		".inf", ".Inf", ".INF",
		"-.inf", "-.Inf", "-.INF",
		".nan", ".NaN", ".NAN":
		return false
	}
	// Starts with special char
	first := s[0]
	if first == '!' || first == '&' || first == '*' || first == '?' ||
		first == '|' || first == '>' || first == '\'' || first == '"' ||
		first == '%' || first == '@' || first == '`' || first == '#' ||
		first == '-' || first == '[' || first == ']' || first == '{' || first == '}' ||
		first == ',' {
		if first == '-' && len(s) > 1 && !isDigit(s[1]) && s[1] != ' ' {
			// "-abc" is usually fine as plain in YAML but conservative check:
		} else {
			return false
		}
	}
	if first == ' ' || first == '\t' {
		return false
	}
	// Must not look like a number/bool/null
	if _, err := NumberFromString(s); err == nil {
		return false
	}
	// Various embedded sequences that break plain
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\t' {
			return false
		}
		if c == ':' && (i+1 == len(s) || s[i+1] == ' ') {
			return false
		}
		if c == '#' && i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') {
			return false
		}
		if c < 0x20 || c == 0x7f {
			return false
		}
	}
	// Must not end in trailing space
	if s[len(s)-1] == ' ' || s[len(s)-1] == '\t' {
		return false
	}
	return true
}

func isDigit(b byte) bool { return b >= '0' && b <= '9' }

func yamlLiteralBlock(s string, depth int) string {
	// Detect chomping indicator for ending newlines
	var suffix string
	endsNewline := strings.HasSuffix(s, "\n")
	if endsNewline {
		// Single trailing newline -> "|"
		// Multiple trailing newlines -> "|+"
		trimmed := strings.TrimRight(s, "\n")
		if len(s)-len(trimmed) > 1 {
			suffix = "+"
		} else {
			suffix = ""
		}
	} else {
		suffix = "-"
	}
	var sb strings.Builder
	sb.WriteString("|")
	sb.WriteString(suffix)
	// Remove trailing newlines for internal representation if no '+'
	content := s
	if suffix != "+" {
		content = strings.TrimRight(content, "\n")
	}
	lines := strings.Split(content, "\n")
	ind := strings.Repeat("  ", depth)
	for _, l := range lines {
		sb.WriteString("\n")
		if l != "" {
			sb.WriteString(ind)
			sb.WriteString(l)
		}
	}
	return sb.String()
}

func doubleQuoteYAML(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if r < 0x20 {
				fmt.Fprintf(&sb, "\\x%02x", r)
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

