func (p *tomlParser) parse() error {
	for {
		p.skipWSAndNL()
		if p.pos >= len(p.src) {
			return nil
		}
		c := p.src[p.pos]
		if c == '#' {
			p.skipToEOL()
			continue
		}
		if c == '[' {
			if err := p.parseTableHeader(); err != nil {
				return err
			}
			continue
		}
		// key = value
		if err := p.parseKeyValue(p.current); err != nil {
			return err
		}
	}
