func (p *tomlParser) errf(format string, args ...interface{}) error {
	return fmt.Errorf("toml: line %d: "+format, append([]interface{}{p.line}, args...)...)
}

func (p *tomlParser) skipWS() {
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == ' ' || c == '\t' {
			p.pos++
		} else {
			return
		}
	}
}

func (p *tomlParser) skipWSAndNL() {
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		switch c {
		case ' ', '\t':
			p.pos++
		case '\n':
			p.pos++
			p.line++
		case '#':
			p.skipToEOL()
		default:
			return
		}
	}
}

func (p *tomlParser) skipToEOL() {
	for p.pos < len(p.src) && p.src[p.pos] != '\n' {
		p.pos++
	}
}

func (p *tomlParser) skipToEOLAndComment() error {
	p.skipWS()
	if p.pos >= len(p.src) {
		return nil
	}
	if p.src[p.pos] == '#' {
		p.skipToEOL()
	}
	if p.pos < len(p.src) {
		if p.src[p.pos] != '\n' {
			return p.errf("expected newline, got %q", p.src[p.pos])
		}
		p.pos++
		p.line++
	}
	return nil
}

func (p *tomlParser) parseTableHeader() error {
	// p.src[p.pos] == '['
	p.pos++
	isArray := false
	if p.pos < len(p.src) && p.src[p.pos] == '[' {
		isArray = true
		p.pos++
	}
	keys, err := p.parseKeyPath()
	if err != nil {
		return err
	}
	p.skipWS()
	if p.pos >= len(p.src) || p.src[p.pos] != ']' {
		return p.errf("expected ']', got %q", peekChar(p.src, p.pos))
	}
	p.pos++
	if isArray {
		if p.pos >= len(p.src) || p.src[p.pos] != ']' {
			return p.errf("expected ']]', got %q", peekChar(p.src, p.pos))
		}
		p.pos++
	}
	if err := p.skipToEOLAndComment(); err != nil {
		return err
	}
	// Navigate path
	m := p.root
	for i, k := range keys {
		if i == len(keys)-1 {
			if isArray {
				// create/append array-of-tables
				existing, ok := m.Get(k)
				var arr []Value
				if ok {
					a, isArr := existing.([]Value)
					if !isArr {
						return p.errf("key %q is not an array of tables", k)
					}
					arr = a
				}
				newT := NewOrderedMap()
				arr = append(arr, newT)
				m.Set(k, arr)
				p.current = newT
			} else {
				existing, ok := m.Get(k)
				if ok {
					switch ev := existing.(type) {
					case *OrderedMap:
						p.current = ev
					case []Value:
						// Array of tables - use last one
						if len(ev) == 0 {
							return p.errf("empty array of tables %q", k)
						}
						last, isMap := ev[len(ev)-1].(*OrderedMap)
						if !isMap {
							return p.errf("array %q is not of tables", k)
						}
						p.current = last
					default:
						return p.errf("key %q already has non-table value", k)
					}
				} else {
					nt := NewOrderedMap()
					m.Set(k, nt)
					p.current = nt
				}
			}
		} else {
			existing, ok := m.Get(k)
			if !ok {
				nt := NewOrderedMap()
				m.Set(k, nt)
				m = nt
			} else {
				switch ev := existing.(type) {
				case *OrderedMap:
					m = ev
				case []Value:
					if len(ev) == 0 {
						return p.errf("empty array of tables %q", k)
					}
					last, isMap := ev[len(ev)-1].(*OrderedMap)
					if !isMap {
						return p.errf("array %q is not of tables", k)
					}
					m = last
				default:
					return p.errf("key %q already has non-table value", k)
				}
			}
		}
	}
	return nil
}

func (p *tomlParser) parseKeyPath() ([]string, error) {
	var keys []string
	for {
		p.skipWS()
		k, err := p.parseKey()
		if err != nil {
			return nil, err
		}
		keys = append(keys, k)
		p.skipWS()
		if p.pos < len(p.src) && p.src[p.pos] == '.' {
			p.pos++
			continue
		}
		break
	}
	return keys, nil
}

func (p *tomlParser) parseKey() (string, error) {
	if p.pos >= len(p.src) {
		return "", p.errf("unexpected end of input")
	}
	c := p.src[p.pos]
	if c == '"' {
		return p.parseBasicString()
	}
	if c == '\'' {
		return p.parseLiteralString()
	}
	// Bare key
	start := p.pos
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c == '-' {
			p.pos++
		} else {
			break
		}
	}
	if p.pos == start {
		return "", p.errf("expected '.' or '=', but got '%s' instead", peekChar(p.src, p.pos))
	}
	return p.src[start:p.pos], nil
}

func peekChar(s string, pos int) string {
	if pos >= len(s) {
		return ""
	}
	return string(s[pos])
}

func (p *tomlParser) parseKeyValue(m *OrderedMap) error {
	keys, err := p.parseKeyPath()
	if err != nil {
		return err
	}
	p.skipWS()
	if p.pos >= len(p.src) || p.src[p.pos] != '=' {
		return p.errf("expected '.' or '=', but got '%s' instead", peekChar(p.src, p.pos))
	}
	p.pos++
	p.skipWS()
	v, err := p.parseValue()
	if err != nil {
		return err
	}
	if err := p.skipToEOLAndComment(); err != nil {
		return err
	}
	// Navigate/create path
	cm := m
	for i, k := range keys {
		if i == len(keys)-1 {
			cm.Set(k, v)
		} else {
			existing, ok := cm.Get(k)
			if !ok {
				nt := NewOrderedMap()
				cm.Set(k, nt)
				cm = nt
			} else {
				inner, isMap := existing.(*OrderedMap)
				if !isMap {
					return p.errf("key %q already has non-table value", k)
				}
				cm = inner
			}
		}
	}
	return nil
}

func (p *tomlParser) parseValue() (Value, error) {
	p.skipWS()
	if p.pos >= len(p.src) {
		return nil, p.errf("unexpected end of input, expected value")
	}
	c := p.src[p.pos]
	switch {
	case c == '"':
		// Basic string or multi-line basic
		if p.pos+2 < len(p.src) && p.src[p.pos+1] == '"' && p.src[p.pos+2] == '"' {
			return p.parseMultilineBasic()
		}
		s, err := p.parseBasicString()
		return s, err
	case c == '\'':
		if p.pos+2 < len(p.src) && p.src[p.pos+1] == '\'' && p.src[p.pos+2] == '\'' {
			return p.parseMultilineLiteral()
		}
		return p.parseLiteralString()
	case c == '[':
		return p.parseArray()
	case c == '{':
		return p.parseInlineTable()
	case c == 't' || c == 'f':
		return p.parseBool()
	}
	// Numeric or date-like
	return p.parseNumberOrDate()
}

func (p *tomlParser) parseBasicString() (string, error) {
	// current is '"'
	p.pos++
	var sb strings.Builder
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == '"' {
			p.pos++
			return sb.String(), nil
		}
		if c == '\n' {
			return "", p.errf("unterminated basic string")
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.src) {
				return "", p.errf("unterminated basic string")
			}
			esc := p.src[p.pos]
			p.pos++
			switch esc {
			case 'b':
				sb.WriteByte('\b')
			case 't':
				sb.WriteByte('\t')
			case 'n':
				sb.WriteByte('\n')
			case 'f':
				sb.WriteByte('\f')
			case 'r':
				sb.WriteByte('\r')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case 'u':
				if p.pos+4 > len(p.src) {
					return "", p.errf("invalid unicode escape")
				}
				r, err := strconv.ParseUint(p.src[p.pos:p.pos+4], 16, 32)
				if err != nil {
					return "", p.errf("invalid unicode escape")
				}
				p.pos += 4
				sb.WriteRune(rune(r))
			case 'U':
				if p.pos+8 > len(p.src) {
					return "", p.errf("invalid unicode escape")
				}
				r, err := strconv.ParseUint(p.src[p.pos:p.pos+8], 16, 32)
				if err != nil {
					return "", p.errf("invalid unicode escape")
				}
				p.pos += 8
				sb.WriteRune(rune(r))
			default:
				return "", p.errf("invalid escape \\%c", esc)
			}
			continue
		}
		sb.WriteByte(c)
		p.pos++
	}
	return "", p.errf("unterminated basic string")
}

func (p *tomlParser) parseLiteralString() (string, error) {
	p.pos++
	start := p.pos
	for p.pos < len(p.src) {
		if p.src[p.pos] == '\'' {
			s := p.src[start:p.pos]
			p.pos++
			return s, nil
		}
		if p.src[p.pos] == '\n' {
			return "", p.errf("unterminated literal string")
		}
		p.pos++
	}
	return "", p.errf("unterminated literal string")
}

func (p *tomlParser) parseMultilineBasic() (string, error) {
	p.pos += 3
	// Skip leading newline
	if p.pos < len(p.src) && p.src[p.pos] == '\n' {
		p.pos++
		p.line++
	}
	var sb strings.Builder
	for p.pos < len(p.src) {
		// End: """
		if strings.HasPrefix(p.src[p.pos:], "\"\"\"") {
			// Allow 4 or 5 quotes to mean close + extra
			p.pos += 3
			// Count trailing quotes (up to 2 extra allowed)
			for i := 0; i < 2 && p.pos < len(p.src) && p.src[p.pos] == '"'; i++ {
				sb.WriteByte('"')
				p.pos++
			}
			return sb.String(), nil
		}
		c := p.src[p.pos]
		if c == '\\' {
			// Line ending backslash = trim following whitespace
			if p.pos+1 < len(p.src) && (p.src[p.pos+1] == '\n' || p.src[p.pos+1] == ' ' || p.src[p.pos+1] == '\t') {
				// Skip to next non-whitespace
				p.pos++
				for p.pos < len(p.src) && (p.src[p.pos] == ' ' || p.src[p.pos] == '\t' || p.src[p.pos] == '\n') {
					if p.src[p.pos] == '\n' {
						p.line++
					}
					p.pos++
				}
				continue
			}
			// Regular escape - reuse logic
			p.pos++
			esc := p.src[p.pos]
			p.pos++
			switch esc {
			case 'b':
				sb.WriteByte('\b')
			case 't':
				sb.WriteByte('\t')
			case 'n':
				sb.WriteByte('\n')
			case 'f':
				sb.WriteByte('\f')
			case 'r':
				sb.WriteByte('\r')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case 'u':
				if p.pos+4 > len(p.src) {
					return "", p.errf("invalid unicode escape")
				}
				r, _ := strconv.ParseUint(p.src[p.pos:p.pos+4], 16, 32)
				p.pos += 4
				sb.WriteRune(rune(r))
			case 'U':
				if p.pos+8 > len(p.src) {
					return "", p.errf("invalid unicode escape")
				}
				r, _ := strconv.ParseUint(p.src[p.pos:p.pos+8], 16, 32)
				p.pos += 8
				sb.WriteRune(rune(r))
			}
			continue
		}
		if c == '\n' {
			p.line++
		}
		sb.WriteByte(c)
		p.pos++
	}
	return "", p.errf("unterminated multi-line basic string")
}

func (p *tomlParser) parseMultilineLiteral() (string, error) {
	p.pos += 3
	if p.pos < len(p.src) && p.src[p.pos] == '\n' {
		p.pos++
		p.line++
	}
	start := p.pos
	for p.pos < len(p.src) {
		if strings.HasPrefix(p.src[p.pos:], "'''") {
			s := p.src[start:p.pos]
			p.pos += 3
			for i := 0; i < 2 && p.pos < len(p.src) && p.src[p.pos] == '\''; i++ {
				s += "'"
				p.pos++
			}
			return s, nil
		}
		if p.src[p.pos] == '\n' {
			p.line++
		}
		p.pos++
	}
	return "", p.errf("unterminated multi-line literal string")
}

func (p *tomlParser) parseBool() (Value, error) {
	if strings.HasPrefix(p.src[p.pos:], "true") {
		p.pos += 4
		return true, nil
	}
	if strings.HasPrefix(p.src[p.pos:], "false") {
		p.pos += 5
		return false, nil
	}
	return nil, p.errf("invalid bool")
}

func (p *tomlParser) parseArray() ([]Value, error) {
	p.pos++ // consume '['
	var arr []Value
	for {
		p.skipWSAndNL()
		if p.pos >= len(p.src) {
			return nil, p.errf("unterminated array")
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return arr, nil
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		arr = append(arr, v)
		p.skipWSAndNL()
		if p.pos >= len(p.src) {
			return nil, p.errf("unterminated array")
		}
		if p.src[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return arr, nil
		}
		return nil, p.errf("expected ',' or ']' in array")
	}
}

func (p *tomlParser) parseInlineTable() (*OrderedMap, error) {
	p.pos++ // consume '{'
	m := NewOrderedMap()
	p.skipWS()
	if p.pos < len(p.src) && p.src[p.pos] == '}' {
		p.pos++
		return m, nil
	}
	for {
		p.skipWS()
		if err := p.parseKeyValue(m); err != nil {
			return nil, err
		}
		// After parseKeyValue, it consumes up to newline, but inline tables don't have newlines.
		// Our skipToEOLAndComment allows newlines too. For inline, we need special handling.
		// Simplified: re-parse but only one line.
		_ = m
		p.skipWS()
		if p.pos >= len(p.src) {
			return nil, p.errf("unterminated inline table")
		}
		if p.src[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.src[p.pos] == '}' {
			p.pos++
			return m, nil
		}
		return nil, p.errf("expected ',' or '}' in inline table")
	}
}

func (p *tomlParser) parseNumberOrDate() (Value, error) {
	// Read until whitespace/end/comma/bracket/newline
	start := p.pos
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == ',' || c == ']' || c == '}' || c == '#' {
			break
		}
		p.pos++
	}
	tok := p.src[start:p.pos]
	if tok == "" {
		return nil, p.errf("expected value")
	}
	// Check for date/datetime pattern: contains '-' (not as sign) or ':' or 'T'
	if isDateLike(tok) {
		// Keep as string, since our Value has no dedicated time type.
		return tok, nil
	}
	// Special float values
	switch tok {
	case "inf", "+inf":
		if p.noConv {
			return Number{IsFloat: true, F: math.MaxFloat64, Src: formatFloat(math.MaxFloat64)}, nil
		}
		return "Infinity", nil
	case "-inf":
		if p.noConv {
			return Number{IsFloat: true, F: -math.MaxFloat64, Src: formatFloat(-math.MaxFloat64)}, nil
		}
		return "-Infinity", nil
	case "nan", "+nan", "-nan":
		if p.noConv {
			return nil, nil
		}
		return "NaN", nil
	}
	// Remove underscores (TOML allows underscore separators in numbers)
	clean := strings.ReplaceAll(tok, "_", "")
	// Hex/Oct/Bin integer
	if strings.HasPrefix(clean, "0x") || strings.HasPrefix(clean, "0X") {
		if i, err := strconv.ParseInt(clean[2:], 16, 64); err == nil {
			return Number{I: i, Src: strconv.FormatInt(i, 10)}, nil
		}
	}
	if strings.HasPrefix(clean, "0o") || strings.HasPrefix(clean, "0O") {
		if i, err := strconv.ParseInt(clean[2:], 8, 64); err == nil {
			return Number{I: i, Src: strconv.FormatInt(i, 10)}, nil
		}
	}
	if strings.HasPrefix(clean, "0b") || strings.HasPrefix(clean, "0B") {
		if i, err := strconv.ParseInt(clean[2:], 2, 64); err == nil {
			return Number{I: i, Src: strconv.FormatInt(i, 10)}, nil
		}
	}
	// Try int
	if !strings.ContainsAny(clean, ".eE") {
		if i, err := strconv.ParseInt(clean, 10, 64); err == nil {
			return Number{I: i, Src: strconv.FormatInt(i, 10)}, nil
		}
	}
	// Float
	if f, err := strconv.ParseFloat(clean, 64); err == nil {
		return Number{IsFloat: true, F: f, Src: clean}, nil
	}
	return nil, p.errf("invalid value %q", tok)
}

func isDateLike(s string) bool {
	if len(s) < 4 {
		return false
	}
	// Check for YYYY-MM-DD prefix
	if len(s) >= 10 && s[4] == '-' && s[7] == '-' {
		return true
	}
	// Time like HH:MM:SS
	if len(s) >= 5 && s[2] == ':' {
		return true
	}
	return false
}

// ---- TOML Encoder ----

// EncodeTOML encodes a Value as TOML.
func EncodeTOML(v Value, opts *Options) ([]byte, error) {
	indent := opts != nil && opts.Indent
	noConv := opts != nil && opts.NoConvert
	enc := &tomlEncoder{indent: indent, noConv: noConv}
	m, ok := v.(*OrderedMap)
	if !ok {
		// Only tables allowed at the top. Return error or empty.
		// BurntSushi/toml would panic; let's emit the value as a bare literal to match observed behavior.
		buf := bytes.NewBuffer(nil)
		enc.emitScalar(buf, v)
		return buf.Bytes(), nil
	}
	buf := bytes.NewBuffer(nil)
	enc.encodeRoot(buf, m)
	return buf.Bytes(), nil
}

type tomlEncoder struct {
	indent bool
	noConv bool
}

func (e *tomlEncoder) indentStr(depth int) string {
	if !e.indent {
		return ""
	}
	return strings.Repeat("  ", depth)
}

// encodeRoot emits a top-level table.
func (e *tomlEncoder) encodeRoot(buf *bytes.Buffer, m *OrderedMap) {
	e.emitTable(buf, m, []string{}, 0)
}

// emitTable emits the simple (non-table) keys first, then sub-tables.
func (e *tomlEncoder) emitTable(buf *bytes.Buffer, m *OrderedMap, path []string, depth int) {
	// Emit non-table, non-array-of-table values first
	for _, kv := range m.Pairs {
		ks, _ := kv.Key.(string)
		if !e.isTable(kv.Value) && !e.isArrayOfTables(kv.Value) {
			buf.WriteString(e.indentStr(depth))
			buf.WriteString(escapeTOMLKey(ks))
			buf.WriteString(" = ")
			e.emitValue(buf, kv.Value)
			buf.WriteByte('\n')
		}
	}
	// Emit sub-tables and arrays of tables
	for _, kv := range m.Pairs {
		ks, _ := kv.Key.(string)
		switch vv := kv.Value.(type) {
		case *OrderedMap:
			if len(vv.Pairs) == 0 {
				continue
			}
			buf.WriteByte('\n')
			subPath := append(append([]string{}, path...), ks)
			buf.WriteString(e.indentStr(depth))
			buf.WriteByte('[')
			buf.WriteString(tomlKeyPath(subPath))
			buf.WriteString("]\n")
			e.emitTable(buf, vv, subPath, depth+1)
		case []Value:
			if len(vv) == 0 {
				continue
			}
			if isAllTables(vv) {
				subPath := append(append([]string{}, path...), ks)
				for _, item := range vv {
					mm := item.(*OrderedMap)
					buf.WriteByte('\n')
					buf.WriteString(e.indentStr(depth))
					buf.WriteString("[[")
					buf.WriteString(tomlKeyPath(subPath))
					buf.WriteString("]]\n")
					e.emitTable(buf, mm, subPath, depth+1)
				}
			}
		}
	}
}

func (e *tomlEncoder) isTable(v Value) bool {
	_, ok := v.(*OrderedMap)
	return ok
}

func (e *tomlEncoder) isArrayOfTables(v Value) bool {
	arr, ok := v.([]Value)
	if !ok {
		return false
	}
	return isAllTables(arr)
}

func isAllTables(arr []Value) bool {
	if len(arr) == 0 {
		return false
	}
	for _, v := range arr {
		if _, ok := v.(*OrderedMap); !ok {
			return false
		}
	}
	return true
}

// emitValue emits a scalar or inline array/table.
func (e *tomlEncoder) emitValue(buf *bytes.Buffer, v Value) {
	switch x := v.(type) {
	case nil:
		// TOML has no null. Leave empty (matches original behavior of producing nothing)
	case bool:
		if x {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case string:
		emitTOMLString(buf, x)
	case Number:
		if x.IsFloat {
			f := x.F
			if isNaN(f) {
				if e.noConv {
					buf.WriteString("nan")
				} else {
					emitTOMLString(buf, "NaN")
				}
				return
			}
			if isInf(f, 1) {
				if e.noConv {
					buf.WriteString("inf")
				} else {
					emitTOMLString(buf, "Infinity")
				}
				return
			}
			if isInf(f, -1) {
				if e.noConv {
					buf.WriteString("-inf")
				} else {
					emitTOMLString(buf, "-Infinity")
				}
				return
			}
			buf.WriteString(tomlFloatFormat(f))
		} else {
			buf.WriteString(x.JSONString())
		}
	case []Value:
		buf.WriteByte('[')
		for i, item := range x {
			if i > 0 {
				buf.WriteString(", ")
			}
			e.emitValue(buf, item)
		}
		buf.WriteByte(']')
	case *OrderedMap:
		// inline table
		buf.WriteByte('{')
		for i, p := range x.Pairs {
			if i > 0 {
				buf.WriteString(", ")
			}
			ks, _ := p.Key.(string)
			buf.WriteString(escapeTOMLKey(ks))
			buf.WriteString(" = ")
			e.emitValue(buf, p.Value)
		}
		buf.WriteByte('}')
	}
}

func (e *tomlEncoder) emitScalar(buf *bytes.Buffer, v Value) {
	e.emitValue(buf, v)
}

// tomlFloatFormat produces BurntSushi/toml-like float formatting.
// Integers with no fractional part get ".0" suffix.
// Exponent form is avoided when the magnitude would produce a long decimal
// (but in observed output, 1.7976e+308 became full decimal).
func tomlFloatFormat(f float64) string {
	s := strconv.FormatFloat(f, 'f', -1, 64)
	if !strings.Contains(s, ".") {
		s += ".0"
	}
	return s
}

// emitTOMLString emits a basic string with proper escaping.
func emitTOMLString(buf *bytes.Buffer, s string) {
	buf.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			buf.WriteString(`\"`)
		case '\\':
			buf.WriteString(`\\`)
		case '\n':
			buf.WriteString(`\n`)
		case '\r':
			buf.WriteString(`\r`)
		case '\t':
			buf.WriteString(`\t`)
		case '\b':
			buf.WriteString(`\b`)
		case '\f':
			buf.WriteString(`\f`)
		default:
			if r < 0x20 {
				fmt.Fprintf(buf, "\\u%04x", r)
			} else {
				buf.WriteRune(r)
			}
		}
	}
	buf.WriteByte('"')
}

// escapeTOMLKey returns a TOML-safe key. Uses bare if possible, else quoted.
func escapeTOMLKey(k string) string {
	if k == "" {
		return "\"\""
	}
	// Bare allowed: [A-Za-z0-9_-]+
	allBare := true
	for _, r := range k {
		if !((r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '_' || r == '-') {
			allBare = false
			break
		}
	}
	if allBare {
		return k
	}
	var buf bytes.Buffer
	emitTOMLString(&buf, k)
	return buf.String()
}

func tomlKeyPath(path []string) string {
	parts := make([]string, len(path))
	for i, p := range path {
		parts[i] = escapeTOMLKey(p)
	}
	return strings.Join(parts, ".")
}

