	src  string
	pos  int
	line int
}

func (p *hclParser) errf(format string, args ...interface{}) error {
	return fmt.Errorf("At %d:0: "+format, append([]interface{}{p.line}, args...)...)
}

func (p *hclParser) skipWS() {
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		switch {
		case c == ' ' || c == '\t' || c == '\r':
			p.pos++
		case c == '\n':
			p.pos++
			p.line++
		case c == '#':
			for p.pos < len(p.src) && p.src[p.pos] != '\n' {
				p.pos++
			}
		case c == '/' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '/':
			for p.pos < len(p.src) && p.src[p.pos] != '\n' {
				p.pos++
			}
		case c == '/' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '*':
			p.pos += 2
			for p.pos+1 < len(p.src) && !(p.src[p.pos] == '*' && p.src[p.pos+1] == '/') {
				if p.src[p.pos] == '\n' {
					p.line++
				}
				p.pos++
			}
			if p.pos+1 < len(p.src) {
				p.pos += 2
			}
		default:
			return
		}
	}
}

// parseBody parses a sequence of key = value / block statements into a map.
// If inBlock is true, parsing stops at the matching '}'.
func (p *hclParser) parseBody(inBlock bool) (*OrderedMap, error) {
	m := NewOrderedMap()
	for {
		p.skipWS()
		if p.pos >= len(p.src) {
			if inBlock {
				return nil, p.errf("expected '}'")
			}
			return m, nil
		}
		if p.src[p.pos] == '}' {
			if inBlock {
				return m, nil
			}
			return nil, p.errf("unexpected '}'")
		}
		// Parse an identifier or string as the first token.
		key, err := p.parseIdentOrString()
		if err != nil {
			return nil, err
		}
		p.skipWS()
		// Gather labels (more identifiers/strings) up to '=' or '{'
		var labels []string
		for {
			if p.pos >= len(p.src) {
				return nil, p.errf("unexpected end of input")
			}
			c := p.src[p.pos]
			if c == '=' || c == '{' {
				break
			}
			if c == '\n' || c == '}' {
				return nil, p.errf("expected '=' or '{'")
			}
			lbl, err := p.parseIdentOrString()
			if err != nil {
				return nil, err
			}
			labels = append(labels, lbl)
			p.skipWS()
		}
		if p.src[p.pos] == '=' {
			p.pos++
			p.skipWS()
			v, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			// Assignments can appear multiple times; replace the existing value.
			m.Set(key, v)
		} else {
			// block: {
			p.pos++
			body, err := p.parseBody(true)
			if err != nil {
				return nil, err
			}
			if p.pos >= len(p.src) || p.src[p.pos] != '}' {
				return nil, p.errf("expected '}'")
			}
			p.pos++
			block := wrapBlock(body, labels)
			// Merge with existing value if present.
			existing, ok := m.Get(key)
			if ok {
				merged, err := mergeHCL(existing, block)
				if err != nil {
					return nil, err
				}
				m.Set(key, merged)
			} else {
				m.Set(key, block)
			}
		}
		// Allow optional comma separator (mostly for inline maps)
		p.skipWS()
		if p.pos < len(p.src) && p.src[p.pos] == ',' {
			p.pos++
		}
	}
}

// wrapBlock wraps an object body with its label layers (arrays of objects).
func wrapBlock(body *OrderedMap, labels []string) Value {
	// Innermost value is []Value{body}
	cur := []Value{body}
	for i := len(labels) - 1; i >= 0; i-- {
		m := NewOrderedMap()
		m.Set(labels[i], cur)
		cur = []Value{m}
	}
	return cur
}

// mergeHCL merges two HCL block values (arrays of maps) together.
func mergeHCL(a, b Value) (Value, error) {
	av, aOK := a.([]Value)
	bv, bOK := b.([]Value)
	if !aOK || !bOK {
		// Fall back: append
		if aOK {
			return append(av, b), nil
		}
		return []Value{a, b}, nil
	}
	// For labels: when both are single-object arrays, merge keys within the object.
	if len(av) == 1 && len(bv) == 1 {
		am, aM := av[0].(*OrderedMap)
		bm, bM := bv[0].(*OrderedMap)
		if aM && bM {
			// Merge bm into am: for each key, if both present and both arrays of maps, recurse.
			for _, p := range bm.Pairs {
				existing, ok := am.Get(p.Key)
				if ok {
					merged, err := mergeHCL(existing, p.Value)
					if err != nil {
						return nil, err
					}
					am.Set(p.Key, merged)
				} else {
					am.Set(p.Key, p.Value)
				}
			}
			return av, nil
		}
	}
	// Otherwise concatenate
	return append(av, bv...), nil
}

func (p *hclParser) parseIdentOrString() (string, error) {
	if p.pos >= len(p.src) {
		return "", p.errf("expected identifier or string")
	}
	c := p.src[p.pos]
	if c == '"' {
		return p.parseDQString()
	}
	// Bare identifier: letters, digits, -, _
	start := p.pos
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c == '-' {
			p.pos++
		} else {
			break
		}
	}
	if p.pos == start {
		return "", p.errf("expected identifier")
	}
	return p.src[start:p.pos], nil
}

func (p *hclParser) parseDQString() (string, error) {
	if p.src[p.pos] != '"' {
		return "", p.errf("expected '\"'")
	}
	p.pos++
	var sb strings.Builder
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == '"' {
			p.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.src) {
				return "", p.errf("unterminated string")
			}
			esc := p.src[p.pos]
			p.pos++
			switch esc {
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
				sb.WriteByte('\t')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case 'u':
				if p.pos+4 > len(p.src) {
					return "", p.errf("invalid unicode escape")
				}
				r, _ := strconv.ParseUint(p.src[p.pos:p.pos+4], 16, 32)
				p.pos += 4
				sb.WriteRune(rune(r))
			default:
				sb.WriteByte(esc)
			}
			continue
		}
		if c == '\n' {
			p.line++
		}
		sb.WriteByte(c)
		p.pos++
	}
	return "", p.errf("unterminated string")
}

func (p *hclParser) parseValue() (Value, error) {
	p.skipWS()
	if p.pos >= len(p.src) {
		return nil, p.errf("expected value")
	}
	c := p.src[p.pos]
	switch {
	case c == '"':
		s, err := p.parseDQString()
		return s, err
	case c == '[':
		return p.parseArray()
	case c == '{':
		return p.parseObjectValue()
	case c == '<' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '<':
		return p.parseHeredoc()
	case c == '-' || (c >= '0' && c <= '9'):
		return p.parseNumber()
	}
	// identifier: true/false/null or error
	start := p.pos
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' {
			p.pos++
		} else {
			break
		}
	}
	tok := p.src[start:p.pos]
	switch tok {
	case "true":
		return true, nil
	case "false":
		return false, nil
	case "null":
		return nil, nil
	}
	return nil, p.errf("unexpected token %q", tok)
}

func (p *hclParser) parseArray() ([]Value, error) {
	p.pos++
	var arr []Value
	for {
		p.skipWS()
		if p.pos >= len(p.src) {
			return nil, p.errf("unterminated array")
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return arr, nil
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		arr = append(arr, v)
		p.skipWS()
		if p.pos >= len(p.src) {
			return nil, p.errf("unterminated array")
		}
		if p.src[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return arr, nil
		}
		return nil, p.errf("expected ',' or ']'")
	}
}

// parseObjectValue parses an HCL object literal `{ ... }` value. In HCL v1
// semantics, such a value becomes []Value{*OrderedMap{...}}.
func (p *hclParser) parseObjectValue() (Value, error) {
	p.pos++ // {
	inner, err := p.parseBody(true)
	if err != nil {
		return nil, err
	}
	if p.pos >= len(p.src) || p.src[p.pos] != '}' {
		return nil, p.errf("expected '}'")
	}
	p.pos++
	return []Value{inner}, nil
}

func (p *hclParser) parseHeredoc() (string, error) {
	// << or <<- marker
	p.pos += 2
	indented := false
	if p.pos < len(p.src) && p.src[p.pos] == '-' {
		indented = true
		p.pos++
	}
	// Read tag until newline
	tagStart := p.pos
	for p.pos < len(p.src) && p.src[p.pos] != '\n' {
		p.pos++
	}
	tag := strings.TrimSpace(p.src[tagStart:p.pos])
	if p.pos < len(p.src) {
		p.pos++
		p.line++
	}
	// Read until a line containing only the tag
	var lines []string
	for p.pos < len(p.src) {
		lineStart := p.pos
		for p.pos < len(p.src) && p.src[p.pos] != '\n' {
			p.pos++
		}
		line := p.src[lineStart:p.pos]
		check := line
		if indented {
			check = strings.TrimLeft(line, " \t")
		}
		if check == tag {
			if p.pos < len(p.src) {
				p.pos++
				p.line++
			}
			out := strings.Join(lines, "\n")
			if len(lines) > 0 {
				out += "\n"
			}
			return out, nil
		}
		lines = append(lines, line)
		if p.pos < len(p.src) {
			p.pos++
			p.line++
		}
	}
	return "", p.errf("unterminated heredoc")
}

func (p *hclParser) parseNumber() (Value, error) {
	start := p.pos
	if p.src[p.pos] == '-' {
		p.pos++
	}
	for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
		p.pos++
	}
	isFloat := false
	if p.pos < len(p.src) && p.src[p.pos] == '.' {
		isFloat = true
		p.pos++
		for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
			p.pos++
		}
	}
	if p.pos < len(p.src) && (p.src[p.pos] == 'e' || p.src[p.pos] == 'E') {
		isFloat = true
		p.pos++
		if p.pos < len(p.src) && (p.src[p.pos] == '+' || p.src[p.pos] == '-') {
			p.pos++
		}
		for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
			p.pos++
		}
	}
	tok := p.src[start:p.pos]
	if isFloat {
		f, err := strconv.ParseFloat(tok, 64)
		if err != nil {
			return nil, p.errf("invalid number %q", tok)
		}
		return Number{IsFloat: true, F: f, Src: tok}, nil
	}
	i, err := strconv.ParseInt(tok, 10, 64)
	if err != nil {
		return nil, p.errf("invalid number %q", tok)
	}
	return Number{I: i, Src: tok}, nil
}

// ---- HCL Encoder ----

// EncodeHCL encodes a Value in HCL v1 syntax.
func EncodeHCL(v Value, opts *Options) ([]byte, error) {
	enc := &hclEncoder{}
	var buf bytes.Buffer
	m, ok := v.(*OrderedMap)
	if !ok {
		enc.emitValue(&buf, v, 0)
		return buf.Bytes(), nil
	}
	enc.emitRoot(&buf, m)
	return buf.Bytes(), nil
}

type hclEncoder struct{}

func (e *hclEncoder) emitRoot(buf *bytes.Buffer, m *OrderedMap) {
	for i, p := range m.Pairs {
		if i > 0 {
			buf.WriteString("\n\n")
		}
		ks, _ := p.Key.(string)
		buf.WriteByte('"')
		buf.WriteString(ks)
		buf.WriteString("\" = ")
		e.emitValue(buf, p.Value, 0)
	}
}

func (e *hclEncoder) indent(buf *bytes.Buffer, depth int) {
	for i := 0; i < depth; i++ {
		buf.WriteString("  ")
	}
}

func (e *hclEncoder) emitValue(buf *bytes.Buffer, v Value, depth int) {
	switch x := v.(type) {
	case nil:
		// HCL v1 has no explicit null; emit empty.
	case bool:
		if x {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case string:
		buf.WriteByte('"')
		buf.WriteString(hclEscape(x))
		buf.WriteByte('"')
	case Number:
		if x.IsFloat {
			buf.WriteString(formatFloat(x.F))
		} else {
			buf.WriteString(x.JSONString())
		}
	case []Value:
		// Array - may be array of primitives or array of objects
		if len(x) == 0 {
			buf.WriteString("[]")
			return
		}
		// HCL emitter behavior: arrays of objects are always rendered as
		// multiple block-style objects when the value holds a single
		// embedded object; inline arrays for primitives.
		if allObjects(x) && len(x) == 1 {
			// Single object value -> render as block
			e.emitObject(buf, x[0].(*OrderedMap), depth)
			return
		}
		buf.WriteByte('[')
		for i, it := range x {
			if i > 0 {
				buf.WriteString(", ")
			}
			e.emitValue(buf, it, depth)
		}
		buf.WriteByte(']')
	case *OrderedMap:
		e.emitObject(buf, x, depth)
	}
}

func (e *hclEncoder) emitObject(buf *bytes.Buffer, m *OrderedMap, depth int) {
	buf.WriteString("{\n")
	for i, p := range m.Pairs {
		if i > 0 {
			buf.WriteString("\n\n")
		}
		e.indent(buf, depth+1)
		ks, _ := p.Key.(string)
		buf.WriteByte('"')
		buf.WriteString(ks)
		buf.WriteString("\" = ")
		e.emitValue(buf, p.Value, depth+1)
	}
	buf.WriteByte('\n')
	e.indent(buf, depth)
	buf.WriteByte('}')
}

func allObjects(arr []Value) bool {
	for _, v := range arr {
		if _, ok := v.(*OrderedMap); !ok {
			return false
		}
	}
	return true
}

func hclEscape(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if r < 0x20 {
				fmt.Fprintf(&sb, "\\x%02x", r)
			} else {
				sb.WriteRune(r)
			}
		}
	}
	return sb.String()
}
