// yamlHasContent returns true if b contains any non-whitespace, non-comment,
// non-doc-separator characters.
func yamlHasContent(b []byte) bool {
	lines := splitLines(string(b))
	for _, l := range lines {
		t := l
		for len(t) > 0 && (t[0] == ' ' || t[0] == '\t' || t[0] == '\r') {
			t = t[1:]
		}
		if t == "" || t == "---" || t == "..." {
			continue
		}
		if t[0] == '#' {
			continue
		}
		return true
	}
	return false
}

func splitLines(s string) []string {
	var out []string
	start := 0
	for i := 0; i < len(s); i++ {
		if s[i] == '\n' {
			out = append(out, s[start:i])
			start = i + 1
		}
	}
	if start < len(s) {
		out = append(out, s[start:])
	}
	return out
}
